  for (let i=0;i<NP;i++){
    const q = fr(i*9.7+1);
    let kd = kinds[Math.floor(fr(i*4.3+2)*kinds.length)];
    if (i===0) kd = 'flange';
    if (i===NP-1) kd = (q>.5) ? 'nut' : 'flange';
    const len = (kd==='hub') ? .28 + q*.55 : (kd==='spring') ? .30 + q*.34 : .07 + q*.16;
    const r0 = (kd==='hub') ? .18 + fr(i*7.1+3)*.14 : (kd==='nut') ? .26 + fr(i*7.1+3)*.12 : .42 + fr(i*7.1+3)*.55;
    const r1 = (kd==='cone') ? r0*(.34 + fr(i*5.9+4)*.5) : r0;
    ps.push({ kd:kd, z0:z, len:len, r0:r0, r1:r1,
              bore: .10 + fr(i*11.3+5)*.14,
              nt: 12 + Math.floor(fr(i*3.7+6)*8)*2,
              nb: 5 + Math.floor(fr(i*6.1+7)*5),
              hu: fr(i*13.1+8) });
    z += len;
  }
  S.parts = ps; S.L = z;
}
const ps = S.parts, L = S.L;

