    }
    if (filled){ noStroke(); fill(face[0],face[1],cl(face[2]*(.85+.25*lit),2,98),100); }
    beginShape();
    for (let j=0;j<N2;j++){ const a1=spin+j*TAU/N2; vertex(z1 + r0*kk*Math.sin(a1), r0*Math.cos(a1)); }
