      if (filled){ noStroke(); fill(shade[0], shade[1], cl(shade[2]*.55,1,60), 100); }
      else { ink(58, Math.max(.8,R*.005)); noFill(); }
      ellipse(z1 + rb2*kk*Math.sin(a1), rb2*Math.cos(a1), 2*hr*kk, 2*hr);
